function draw(ctx, size) {
  ctx.imageSmoothingEnabled = false;
  const px = (x, y, w, h, c) => { ctx.fillStyle = c; ctx.fillRect(x|0, y|0, w|0, h|0); };

  const O='#051428', Y='#f4c020', YLt='#ffe066', Gun='#4a5568', GunLt='#718096';
  // blaster
  px(10,26,40,14,O); px(11,27,38,12,Gun); px(11,27,38,2,GunLt);
  px(44,28,12,10,O); px(45,29,10,8,Y);
  px(48,31,4,4,YLt);
  // bolts
  px(52,20,4,6,Y); px(56,14,3,5,YLt); px(58,8,2,4,Y);

}
